std::vector<cg3::Polygon2> result;
for (const auto& face : arr.faces())
{
    if (face.is_bounded())
    {
        cg3::Polygon2 polygon;
        for (auto it = face.vertices_begin(); it != face.vertices_end(); ++it)
        {
            const auto& vertex = *it;
            cg3::Point2d p;
            p.x = vertex->point().x();
            p.y = vertex->point().y();
            polygon.pushBack(p);
        }
        result.push_back(polygon);
    }
}
return result;

